          "listenPort": 8421,
          "endpoints": [
            {
              "host": "203.0.113.10",
              "port": 8421
            }
          ],
          "bindInterface": "",
          "socket": {
            "receiveBuffer": 0,
            "sendBuffer": 0
          }
        }
